) values
  ('eod-dispatch-manifest', null, 'End-of-day dispatch manifest', 'operations', 'review-due', false, 'Dispatch Lead', 'DL', 'Aug 2026', 'Feb 2027', 'v3', 'Close out and reconcile every parcel that left the warehouse today.', null, '["Dispatch scanner","Carrier manifest printout","Freight desk login"]'::jsonb, '[]'::jsonb, '[{"type":"info","title":"Scan every outbound parcel against the manifest","body":"Every item that left today must show as scanned. Anything missing gets flagged before you leave, not tomorrow morning."},{"type":"checklist","title":"Reconcile against the carrier pickup sheet","items":["Parcel count matches carrier sheet","Freight-only items logged separately","Damaged-in-warehouse items pulled and noted"]},{"type":"info","title":"File the manifest and email the recap","body":"Save the signed manifest to the Dispatch folder and send the daily recap to the Operations channel."}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["Manifest reconciliation sheet"]'::jsonb, '["supplier-damage-claim"]'::jsonb, '[]'::jsonb, null, '[{"name":"Dispatch Lead","initials":"DL","date":"8 Feb 2026"},{"name":"Operations Manager","initials":"OM","date":"9 Feb 2026"}]'::jsonb),
  ('supplier-damage-claim', null, 'Raise a supplier damage claim', 'operations', 'review-due', false, 'Warehouse Lead', 'WL', 'Aug 2026', 'Jan 2027', 'v2', 'Recover the cost when stock arrives damaged from a supplier.', null, '["Photos of the damage","Supplier invoice number"]'::jsonb, '[]'::jsonb, '[{"type":"info","title":"Photograph the damage before you move the stock","body":"Wide shot, close shot, and the packaging. Suppliers reject claims without packaging photos."},{"type":"info","title":"Raise the RA request with the supplier","body":"Use the supplier RA form and quote the original invoice number."},{"type":"checklist","title":"Log the claim internally","items":["RA number recorded against the PO","Stock quarantined, not resold","Accounts notified for the credit note"]}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["Supplier RA request"]'::jsonb, '["doa-claim","eod-dispatch-manifest"]'::jsonb, '[]'::jsonb, null, '[{"name":"Warehouse Lead","initials":"WL","date":"12 Jan 2026"}]'::jsonb),
  ('stocktake-kegerator-line', null, 'Stocktake a kegerator line', 'operations', 'review-due', false, 'Dispatch Lead', 'DL', 'Aug 2026', 'Apr 2027', 'v2', 'Counting taps, lines and CO2 fittings without breaking a set.', null, '["Stocktake scanner","Line diagram for the SKU"]'::jsonb, '[]'::jsonb, '[{"type":"info","title":"Count by kit, not by part","body":"A kegerator line is sold as a kit. Count complete kits first, then log loose parts separately."},{"type":"checklist","title":"Verify fittings match the SKU","items":["Tap count matches label","CO2 regulator present","Line diagram matches physical unit"]}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["eod-dispatch-manifest"]'::jsonb, '[]'::jsonb, null, '[{"name":"Dispatch Lead","initials":"DL","date":"2 Apr 2026"}]'::jsonb),
  ('peak-season-dispatch-surge', null, 'Peak season dispatch surge plan', 'operations', 'review-due', false, 'Operations Manager', 'OM', 'Aug 2026', 'Jun 2027', 'v4', 'What changes on the floor when order volume spikes.', null, '[]'::jsonb, '[]'::jsonb, '[{"type":"info","title":"Trigger the surge roster","body":"Once daily orders exceed 40, move to the surge roster and pull in casual floor staff."},{"type":"checklist","title":"Reprioritise the queue","items":["Freight-booked orders first","Click-and-collect same day","Standard delivery within 3 days"]}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["Surge roster template"]'::jsonb, '["eod-dispatch-manifest"]'::jsonb, '[]'::jsonb, null, '[{"name":"Operations Manager","initials":"OM","date":"10 Jun 2026"},{"name":"Dispatch Lead","initials":"DL","date":"11 Jun 2026"}]'::jsonb),
  ('holiday-roster-dispatch-coverage', null, 'Holiday roster dispatch coverage', 'operations', 'review-due', false, 'Dispatch Lead', 'DL', 'Aug 2026', null, 'v1 (draft)', 'Draft — started 2 days ago.', null, '[]'::jsonb, '[]'::jsonb, '[{"type":"info","title":"Draft: confirm minimum floor coverage","body":"This SOP is still being written. Content is not final."}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["peak-season-dispatch-surge"]'::jsonb, '[]'::jsonb, null, '[]'::jsonb),
  ('doa-claim', null, 'Damaged on arrival — the DOA claim', 'cx', 'review-due', false, 'Customer Experience Lead', 'CX', 'Aug 2026', 'Feb 2027', 'v4', 'Photos, carrier window, replace-or-refund call.', 'Never promise a replacement or refund before photos are logged — the carrier claim window depends on it.', '["Order number","Zendesk ticket","Carrier consignment note","Supplier RA form"]'::jsonb, '[]'::jsonb, '[{"type":"info","title":"Get photos before you promise anything","body":"You need a wide shot of the damage, a close-up, and a shot of the packaging. Do this before you tell the customer what happens next — the carrier claim depends on it."},{"type":"info","title":"Log the claim in Zendesk with the DOA macro","body":"Tag it DOA and attach every photo. Heads up: the carrier claim window closes 2 days after the delivery date on freight consignments."},{"type":"decision","title":"Decide: replace, part, or refund","body":"Structural or cosmetic damage on a cabinet usually means a part, not a full replacement. Use judgement, and escalate if you''re unsure.","options":[{"label":"Send a part","detail":"Cosmetic or minor structural damage that a replacement part fixes."},{"label":"Full replacement","detail":"Structural damage that can''t be repaired with a part."},{"label":"Refund","detail":"Customer no longer wants the item, or no replacement stock is available."}]},{"type":"info","title":"Lodge the carrier claim","body":"Use the carrier claim template and attach the consignment note plus your photos."},{"type":"info","title":"Get the supplier RA number","body":"Needed before any replacement stock can be dispatched."},{"type":"checklist","title":"Close the loop with the customer","items":["Resolution confirmed with customer","Zendesk ticket updated with outcome","Accounts notified if a credit note is needed"]}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["DOA claim form","Carrier claim template"]'::jsonb, '["supplier-damage-claim","change-of-mind-return"]'::jsonb, '[]'::jsonb, null, '[{"name":"Customer Experience Lead","initials":"CX","date":"6 Aug 2026"},{"name":"Sales Lead","initials":"SL","date":"6 Aug 2026"}]'::jsonb),
  ('warranty-kegerator-compressor', null, 'Warranty claim: kegerator compressor', 'cx', 'review-due', false, 'Customer Experience Lead', 'CX', 'Aug 2026', 'May 2027', 'v3', 'Serial lookup, fault video, supplier RA number.', null, '["Serial number","Fault video from customer"]'::jsonb, '[]'::jsonb, '[{"type":"info","title":"Look up the serial number","body":"Confirm the unit is inside its warranty window before doing anything else."},{"type":"checklist","title":"Get evidence from the customer","items":["Fault video received","Serial number visible in video or photo","Symptom description logged"]},{"type":"info","title":"Raise the supplier RA","body":"Quote the serial number and attach the fault video to the RA request."}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["Warranty claim form"]'::jsonb, '["doa-claim"]'::jsonb, '[]'::jsonb, null, '[{"name":"Customer Experience Lead","initials":"CX","date":"9 May 2026"}]'::jsonb),
  ('change-of-mind-return', null, 'Change-of-mind return on a bar fridge', 'cx', 'review-due', false, 'Customer Experience Lead', 'CX', 'Aug 2026', 'Sep 2026', 'v2', 'Restocking fee, freight recovery, condition check.', null, '["Order number","Photos of current condition"]'::jsonb, '[]'::jsonb, '[{"type":"info","title":"Check the return window","body":"Change-of-mind returns are accepted within 14 days of delivery, unpacked or not."},{"type":"checklist","title":"Assess condition and freight recovery","items":["Condition photos received","Restocking fee calculated","Return freight cost quoted to customer"]}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["Restocking fee calculator"]'::jsonb, '["doa-claim"]'::jsonb, '[]'::jsonb, null, '[{"name":"Customer Experience Lead","initials":"CX","date":"4 Mar 2026"}]'::jsonb),
  ('escalate-to-manager', null, 'When to escalate to a manager', 'cx', 'review-due', false, 'Customer Experience Lead', 'CX', 'Aug 2026', 'Jul 2027', 'v3', 'Dollar thresholds, tone triggers, the handover note.', null, '[]'::jsonb, '[]'::jsonb, '[{"type":"info","title":"Know the dollar threshold","body":"Any resolution over $500, or any refund without a return, needs manager sign-off before you promise it."},{"type":"checklist","title":"Watch for tone triggers","items":["Customer has asked for a manager directly","Third contact on the same issue","Threat of a chargeback or public review"]},{"type":"info","title":"Write the handover note","body":"One paragraph: what happened, what you''ve already offered, what you need from the manager."}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["doa-claim","change-of-mind-return"]'::jsonb, '[]'::jsonb, null, '[{"name":"Customer Experience Lead","initials":"CX","date":"1 Jul 2026"}]'::jsonb),
  ('pre-site-check-install', null, 'Pre-site check before an install', 'installations', 'review-due', false, 'Installations Lead', 'IL', 'Aug 2026', 'Jun 2027', 'v3', 'Doorways, stairs, floor level, power for the light.', null, '["Site access notes from Sales"]'::jsonb, '[]'::jsonb, '[{"type":"checklist","title":"Confirm access","items":["Narrowest doorway measured","Stairs counted and photographed","Lift access confirmed if above ground floor"]},{"type":"info","title":"Check the floor","body":"Floor must be level to within 5mm across the table footprint. Flag anything worse before install day, not on arrival."},{"type":"info","title":"Confirm power for the light","body":"A pendant light install needs a power point within reach, or the customer needs to arrange one before you arrive."}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["Pre-site checklist"]'::jsonb, '[]'::jsonb, '[]'::jsonb, null, '[{"name":"Installations Lead","initials":"IL","date":"5 Jun 2026"}]'::jsonb),
  ('sparky-required-checks', null, 'Clearances, drainage, when a sparky is mandatory', 'installations', 'review-due', false, 'Installations Lead', 'IL', 'Aug 2026', 'Nov 2026', 'v2', 'For outdoor kitchens, kegerator huts and sauna installs.', null, '[]'::jsonb, '[]'::jsonb, '[{"type":"info","title":"Check clearances","body":"Confirm minimum clearances to boundary and structure per the product manual before install day."},{"type":"info","title":"Check drainage","body":"Any wet area install needs confirmed drainage away from the unit base."},{"type":"info","title":"Know when a licensed electrician is mandatory","body":"Any hardwired connection, or anything outdoors on a dedicated circuit, is licensed-electrician-only. No exceptions."}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["pre-site-check-install"]'::jsonb, '[]'::jsonb, null, '[{"name":"Installations Lead","initials":"IL","date":"3 Nov 2025"}]'::jsonb),
  ('custom-bar-fitout-quote', null, 'Quoting a custom bar fitout', 'sales', 'review-due', false, 'Sales Lead', 'SL', 'Aug 2026', 'Jul 2027', 'v3', 'Measurements, lead times, deposit terms in one quote.', null, '["Room measurements","Style references from customer"]'::jsonb, '[]'::jsonb, '[{"type":"checklist","title":"Capture the essentials","items":["Room measurements confirmed","Power and plumbing points noted","Style references attached"]},{"type":"info","title":"Build the quote","body":"Use the custom quote template. Always include the lead time range and deposit terms on the first page."}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["Custom quote template"]'::jsonb, '["deposit-layby-terms"]'::jsonb, '[]'::jsonb, null, '[{"name":"Sales Lead","initials":"SL","date":"2 Jul 2026"}]'::jsonb),
  ('pool-table-trade-in-valuation', null, 'Trade-in valuation for a pool table', 'sales', 'review-due', false, 'Sales Lead', 'SL', 'Aug 2026', 'Aug 2026', 'v2', 'Condition grading and the trade-in price bands.', null, '["Photos of the table","Slate vs composite confirmed"]'::jsonb, '[]'::jsonb, '[{"type":"info","title":"Confirm slate or composite","body":"Slate tables hold trade-in value far better than composite. Always confirm before quoting a band."},{"type":"checklist","title":"Grade the condition","items":["Cloth condition photographed","Cabinet condition photographed","Pockets and rails checked"]}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["Trade-in valuation sheet"]'::jsonb, '["custom-bar-fitout-quote"]'::jsonb, '[]'::jsonb, null, '[{"name":"Sales Lead","initials":"SL","date":"1 Feb 2026"}]'::jsonb),
  ('cloth-colour-matching', null, 'Matching cloth colour to a client''s room', 'sales', 'review-due', false, 'Sales Lead', 'SL', 'Aug 2026', 'May 2027', 'v1', 'Using the swatch kit without guessing under showroom light.', null, '["Swatch kit"]'::jsonb, '[]'::jsonb, '[{"type":"info","title":"Never match under showroom lighting alone","body":"Showroom lighting skews warm. Ask the customer to photograph the swatch in their own room before confirming."}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["custom-bar-fitout-quote"]'::jsonb, '[]'::jsonb, null, '[{"name":"Sales Lead","initials":"SL","date":"6 May 2026"}]'::jsonb),
  ('deposit-layby-terms', null, 'Deposit and layby terms', 'sales', 'review-due', false, 'Sales Manager', 'SM', 'Aug 2026', 'Apr 2027', 'v2', 'What''s standard, and when to escalate an exception.', null, '[]'::jsonb, '[]'::jsonb, '[{"type":"info","title":"Standard terms","body":"20% deposit, balance due before dispatch. Layby terms cap at 90 days."},{"type":"info","title":"Anything outside standard terms needs manager sign-off","body":"Don''t verbally agree to an exception before it''s approved."}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["Layby agreement template"]'::jsonb, '["custom-bar-fitout-quote"]'::jsonb, '[]'::jsonb, null, '[{"name":"Sales Manager","initials":"SM","date":"3 Apr 2026"}]'::jsonb),
  ('product-photography-checklist', null, 'Product photography checklist', 'marketing', 'review-due', false, 'Marketing Lead', 'ML', 'Aug 2026', 'Jun 2027', 'v2', 'Angles, lighting and file naming for the product catalogue.', null, '["Studio booked","SKU list"]'::jsonb, '[]'::jsonb, '[{"type":"checklist","title":"Shot list","items":["Front, 3/4 and detail angles","Lifestyle shot in showroom setting","Cloth and cabinet colour options"]},{"type":"info","title":"File naming","body":"SKU-angle-number.jpg, lowercase, no spaces."}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, null, '[{"name":"Marketing Lead","initials":"ML","date":"9 Jun 2026"}]'::jsonb),
  ('showroom-social-post', null, 'Boosting a showroom social post', 'marketing', 'review-due', false, 'Marketing Lead', 'ML', 'Aug 2026', null, 'v1 (draft)', 'Draft — budget thresholds not yet confirmed.', null, '[]'::jsonb, '[]'::jsonb, '[{"type":"info","title":"Draft: confirm boost budget approval flow","body":"This SOP is still being written. Content is not final."}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb),
  ('seasonal-sale-page-checklist', null, 'Seasonal sale page checklist', 'marketing', 'review-due', false, 'Marketing Lead', 'ML', 'Aug 2026', 'Jul 2026', 'v3', 'What has to be live before a sale page goes public.', null, '[]'::jsonb, '[]'::jsonb, '[{"type":"checklist","title":"Pre-launch checks","items":["Stock levels confirmed for every sale SKU","Sale pricing verified against margin floor","End date scheduled to auto-revert pricing"]}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, null, '[{"name":"Marketing Lead","initials":"ML","date":"6 Jan 2026"}]'::jsonb),
  ('issuing-credit-note', null, 'Issuing a credit note', 'accounts', 'review-due', false, 'Bookkeeper', 'BK', 'Aug 2026', 'May 2027', 'v2', 'When a claim or return converts to a credit.', null, '["Order number","Approved claim reference"]'::jsonb, '[]'::jsonb, '[{"type":"info","title":"Confirm the claim is approved","body":"A credit note only gets issued against an approved DOA, warranty, or damage claim reference."},{"type":"checklist","title":"Issue and record","items":["Credit note number logged against order","Customer notified","Ledger updated same day"]}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["Credit note template"]'::jsonb, '["doa-claim","supplier-damage-claim"]'::jsonb, '[]'::jsonb, null, '[{"name":"Bookkeeper","initials":"BK","date":"8 May 2026"}]'::jsonb),
  ('reconciling-supplier-invoices', null, 'Reconciling supplier invoices', 'accounts', 'review-due', false, 'Bookkeeper', 'BK', 'Aug 2026', 'Mar 2027', 'v3', 'Matching PO, delivery and invoice before payment.', null, '["Purchase order","Delivery confirmation"]'::jsonb, '[]'::jsonb, '[{"type":"checklist","title":"Three-way match before approving payment","items":["PO quantity matches invoice","Delivery confirmation on file","Pricing matches agreed supplier terms"]}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, null, '[{"name":"Bookkeeper","initials":"BK","date":"2 Mar 2026"}]'::jsonb),
  ('chasing-overdue-trade-account', null, 'Chasing an overdue trade account', 'accounts', 'review-due', false, 'Bookkeeper', 'BK', 'Aug 2026', 'Oct 2026', 'v1', 'The escalation sequence for trade accounts past terms.', null, '[]'::jsonb, '[]'::jsonb, '[{"type":"info","title":"7 days overdue: friendly reminder","body":"Automated email, no action needed unless it bounces."},{"type":"info","title":"14 days overdue: personal call","body":"Call the account holder directly. Log the outcome."},{"type":"info","title":"30 days overdue: escalate to manager","body":"Hold further trade orders until the account is current."}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["issuing-credit-note"]'::jsonb, '[]'::jsonb, null, '[{"name":"Bookkeeper","initials":"BK","date":"1 Oct 2025"}]'::jsonb),
  ('vehicle-fleet-bookings', null, 'Vehicle and fleet bookings', 'exec', 'current', false, 'Executive Assistant (EA)', 'EA', 'Aug 2026', 'Aug 2026', 'v2', 'Booking a delivery van or the forklift for the day.', null, '["Installer''s scheduled delivery state"]'::jsonb, '[]'::jsonb, '[{"type":"decision","title":"Confirm the rental van provider for the installer''s state","body":"Research and confirm the rental company based on which state the installer is scheduled for deliveries in. This applies to external rental van bookings — skip it for forklift bookings.","options":[{"label":"Most states","detail":"Book with Orana or Sixt."},{"label":"Adelaide (SA)","detail":"Book with Bunnings Warehouse — contact their customer service directly to arrange it."},{"label":"Victoria or Queensland","detail":"No usual rental company yet for these states — research and confirm one for this booking."}]},{"type":"info","title":"Notify the installer","body":"DM the installer directly on Slack with the booking details."}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["Fleet booking calendar"]'::jsonb, '[]'::jsonb, '[]'::jsonb, null, '[{"name":"Executive Assistant (EA)","initials":"EA","date":"3 Feb 2026"},{"name":"Exec Admin Team","initials":"EXA","date":"27 Aug 2026"}]'::jsonb),
  ('new-hire-onboarding', 'HR-001', 'New Hire Onboarding', 'exec', 'current', true, 'Executive Assistant (EA)', 'EA', 'Aug 2026', null, 'v1.0 — pending MD approval', 'From confirmed hire to fully set up: contract, Welcome Packet, system access, manager intro.', null, '["Hire confirmation from the Managing Director: full name, job title, start date, pay rate","Contract and NDA templates (shared drive)"]'::jsonb, '[{"name":"Digital Welcome Packet (Google Doc)","note":"The new hire''s checklist, the EA''s live progress tracker, and the record of every platform granted. One per hire."},{"name":"Google Docs — Signature Request","note":"Sends the contract and NDA for e-signature — no physical or email attachment signing."},{"name":"Directory Google Form","note":"New hire''s bank and payment details, linked inside the Welcome Packet."},{"name":"EA-managed platforms","note":"Slack, Asana, Gmail, Shopify"},{"name":"IT Head-managed platforms","note":"Salesforce, Aircall, and anything outside the EA''s access"},{"name":"Xero","note":"Onshore employees need a 1-on-1 Xero Orientation with the Accountant before onboarding is complete."}]'::jsonb, '[{"phase":"Pre-onboarding","type":"checklist","title":"Receive hire confirmation","tags":["approval"],"body":"Confirm full name, job title, start date and pay rate are all on hand before proceeding. Missing anything? Send the Managing Director a written follow-up listing exactly what''s needed.","items":["Full name confirmed","Job title confirmed","Start date confirmed","Pay rate confirmed"]},{"phase":"Pre-onboarding","type":"info","title":"Prepare the contract and NDA","body":"Fill in the candidate''s name, role, start date and pay on the contract template. Save both as LastName_FirstName_Contract_YYYY-MM-DD and LastName_FirstName_NDA_YYYY-MM-DD."},{"phase":"Pre-onboarding","type":"info","title":"Send signature requests via Google Docs","tags":["confidential"],"body":"Send both documents through the signature request feature, one after the other — no need to wait for the first to be signed before sending the second."},{"phase":"Pre-onboarding","type":"info","title":"Confirm both documents are signed","body":"Once both are signed, download and save each to the shared HR drive under the new hire''s folder, and mark the step complete in the Welcome Packet."},{"phase":"Welcome packet & directory form","type":"info","title":"Customise the Welcome Packet","body":"Copy the template, update the new hire''s name, job title and role-specific tools. Confirm platform access needed with the Managing Director and the new hire''s direct manager first. Save as LastName_FirstName_Welcome_Packet."},{"phase":"Welcome packet & directory form","type":"info","title":"Send the Welcome Packet","body":"Email it to the new hire with a note to follow the checklist inside in order — it already contains every link and the Directory Form."},{"phase":"Welcome packet & directory form","type":"info","title":"Confirm the Google Form is submitted","body":"Check the Directory Form response has come through, then mark this phase complete in the Welcome Packet."},{"phase":"System access setup","type":"info","title":"Notify IT Head to begin account creation","body":"Hand off name, role, start date and the confirmed platform list for anything outside the EA''s access (Salesforce, Aircall, etc.)."},{"phase":"System access setup","type":"info","title":"Send Slack invite","body":"All new hires get Slack — no additional approval needed. Add them to the relevant channels for their role."},{"phase":"System access setup","type":"info","title":"Grant Asana access","body":"All new hires get Asana — no additional approval needed. Assign them to the relevant team or board."},{"phase":"System access setup","type":"checklist","title":"Set up remaining EA-managed platforms","tags":["approval"],"body":"Only action platforms on the confirmed list from step 5. Time Doctor is contractors only — never set it up for onshore employees.","items":["Gmail set up (if on the confirmed list)","Shopify set up (if on the confirmed list)"]},{"phase":"System access setup","type":"info","title":"Record platform access in the Welcome Packet","body":"Log each platform live as it''s confirmed active — this document is the sole record of what the new hire has access to."},{"phase":"Final setup & introduction","type":"info","title":"Confirm all accounts are working","body":"Check in with the new hire that every tool is accessible. Escalate anything broken to the IT Head immediately."},{"phase":"Final setup & introduction","type":"info","title":"Schedule intro meeting with manager","body":"Book a calendar meeting between the new hire and their direct manager, confirmed with both parties."},{"phase":"Final setup & introduction","type":"info","title":"Notify the Accountant of new hire details","tags":["confidential"],"body":"Share full name, role and start date, and point them to the Directory Form for payment details. Onshore hires need a 1-on-1 Xero Orientation completed before onboarding can close."},{"phase":"Final setup & introduction","type":"info","title":"Update the internal directory in Slack","body":"Use the Directory Form response to update the internal directory with the new hire''s details."},{"phase":"Final setup & introduction","type":"checklist","title":"Mark onboarding as complete","body":"All of the following must be true before the Welcome Packet is archived as the final record.","items":["Contract and NDA signed and archived","Directory Form submitted","All accounts confirmed working","Platform access logged in the Welcome Packet","Intro meeting with manager scheduled","Xero Orientation completed (onshore only)"]}]'::jsonb, '["Contract signed and saved to the shared HR drive","NDA signed and saved to the shared HR drive","Directory Google Form submitted and confirmed","All required tools and accounts set up and confirmed working","All platforms granted are documented in the Welcome Packet","Intro meeting with direct manager scheduled or completed","Accountant notified for payroll setup","Xero Orientation completed (onshore employees only)","Welcome Packet fully marked complete and archived"]'::jsonb, '[{"when":"Contract or NDA dispute","action":"Escalate to the Managing Director immediately — do not proceed until resolved."},{"when":"New hire unresponsive 3+ business days","action":"Send one follow-up email. If still no response after 24 hours, notify the Managing Director."},{"when":"System access issues","action":"Contact the IT Head directly. Escalate to the Managing Director if unresolved within 1 business day."},{"when":"Missing hire details from the Managing Director","action":"Send a written follow-up listing exactly what''s missing. Don''t send the contract until all four details are confirmed."},{"when":"New hire raises concerns about tools or role","action":"Direct to their role manager. Pay or admin queries go to the Bookkeeper."}]'::jsonb, '["Contract template","NDA template","Directory Google Form","Digital Welcome Packet template"]'::jsonb, '["employee-offboarding","monthly-payroll-sop"]'::jsonb, '[]'::jsonb, null, '[{"name":"Exec Admin Team","initials":"EXA","date":"27 Aug 2026"}]'::jsonb),
  ('employee-offboarding', 'HR-002', 'Employee Offboarding', 'exec', 'current', true, 'Executive Assistant (EA)', 'EA', 'Aug 2026', null, 'v1.0 — pending MD approval', 'Three tracks — immediate termination, grace-period release, or resignation. Access revoked in lock-step with HR-001.', null, '["Which track applies, and the confirmed last working day","The departing employee''s HR-001 Welcome Packet (their access record)"]'::jsonb, '[{"name":"HR-001 Welcome Packet","note":"The access record from onboarding — pull this first as your master revocation list."},{"name":"Slack (private channel)","note":"Where the official written notice goes, with the Bookkeeper tagged for payroll reference."},{"name":"Offboarding Checklist (Google Doc)","note":"New doc per departing employee, built from their HR-001 platform list. The EA''s live tracker and final record."},{"name":"Google Admin","note":"Used to transfer the departing employee''s Gmail files to their manager before deleting the account."},{"name":"Time Doctor","note":"Contractors only — deactivate and archive (don''t delete) for payroll reference."}]'::jsonb, '[{"phase":"Offboarding initiation","type":"decision","title":"Which offboarding track applies?","body":"Know your track before starting — it decides the timeline and who initiates.","options":[{"label":"Track A — Immediate termination","detail":"MD-initiated. Everything, including access revocation, happens the same day."},{"label":"Track B — Grace-period release","detail":"MD-initiated with a 2-week grace period. Employee works normally; access revoked on the last day."},{"label":"Track C — Voluntary resignation","detail":"Employee-initiated. Confirm with the MD in writing before any offboarding step begins."}]},{"phase":"Offboarding initiation","type":"info","title":"Confirm with the MD (Track C only)","tags":["approval"],"body":"Forward the resignation and request written confirmation before doing anything else. Tracks A and B skip this — the MD already initiated."},{"phase":"Offboarding initiation","type":"info","title":"Build the Offboarding Checklist","body":"New Google Doc: LastName_FirstName_Offboarding_YYYY-MM-DD. Pull the platform list from their HR-001 Welcome Packet, or reconstruct it with the IT Head and their manager if none exists. Minimum access for everyone: Slack and Asana — not everyone has Shopify, confirm before actioning."},{"phase":"Offboarding initiation","type":"info","title":"Send official written notice on Slack","tags":["confidential"],"body":"Post in their private channel: confirmed last working day, a neutral acknowledgement, and @Bookkeeper tagged for payroll reference. Track A: send this before any access is revoked."},{"phase":"Offboarding initiation","type":"info","title":"Retrieve platform access records for revocation","body":"Confirm name, role, last working day, track, and the platform list from the Offboarding Checklist so every access revocation step below can be actioned directly. Track A needs same-day revocation."},{"phase":"System access revocation","type":"info","title":"Revoke Asana access","body":"Remove from the workspace and reassign any open tasks to their manager or a teammate."},{"phase":"System access revocation","type":"info","title":"Revoke Shopify access, if applicable","body":"Only action this if Shopify is on the confirmed platform list — not everyone has it."},{"phase":"System access revocation","type":"info","title":"Transfer Gmail files and delete account","body":"Transfer file ownership to their manager via Google Admin first — only once that''s confirmed, permanently delete the account."},{"phase":"System access revocation","type":"info","title":"Remove from Google Drive","body":"Transfer ownership of business-critical files to their manager before removing shared drive and folder access."},{"phase":"System access revocation","type":"info","title":"Revoke Salesforce and Aircall access","body":"Remove access directly in each platform''s admin panel. Don''t mark these complete until removal is verified."},{"phase":"System access revocation","type":"info","title":"Deactivate and archive Time Doctor (contractors only)","body":"Deactivate access, then archive — not delete — the profile. It''s needed for the final pay run."},{"phase":"System access revocation","type":"info","title":"Post general channel announcement on Slack","body":"Name, last day, and a prompt for anyone who needs something from them before EOD. Track A: post this after the private notice and after access is revoked."},{"phase":"System access revocation","type":"info","title":"Deactivate Slack account","body":"End of the last working day, after the announcement and the team''s had a chance to reach out. Track A: deactivate immediately after the announcement."},{"phase":"Physical asset recovery","type":"info","title":"Collect physical assets (onshore only)","body":"The Managing Director collects company assets — typically computer and uniform — in person and confirms receipt in writing. Remote/offshore employees have no equipment to return; skip to payroll."},{"phase":"Physical asset recovery","type":"info","title":"Confirm no assets outstanding (onshore only)","body":"Escalate to the Managing Director immediately if anything is missing or disputed."},{"phase":"Payroll & records finalisation","type":"info","title":"Confirm final payroll with the Bookkeeper","tags":["confidential","approval"],"body":"Onshore: confirm Xero deactivation and the final pay run. Offshore/contractors: confirm the final payment. Paying within 7 days of departure needs the MD''s written confirmation first."},{"phase":"Payroll & records finalisation","type":"info","title":"Remove from Slack directory","body":"Delete their entry — no personal contact details or role info should remain visible."},{"phase":"Payroll & records finalisation","type":"info","title":"Archive all employee records","tags":["confidential"],"body":"Move the contract, NDA, Directory Form entry, HR-001 Welcome Packet and the completed Offboarding Checklist into an ''Offboarded'' HR subfolder."},{"phase":"Payroll & records finalisation","type":"info","title":"Mark offboarding complete and notify the MD","body":"Once every phase is confirmed, mark the Offboarding Checklist complete and send the Managing Director written confirmation."}]'::jsonb, '["Official written notice sent in the employee''s private Slack channel, Bookkeeper tagged","MD''s written confirmation received before proceeding (Track C only)","All access revoked and ticked off against the HR-001 Welcome Packet","IT Head confirmed in writing that Salesforce, Aircall and IT-managed platforms are revoked","Gmail files transferred and account permanently deleted","Google Drive ownership transferred and access removed","Physical assets collected and confirmed (onshore only)","Bookkeeper confirmed final payroll is processed","Employee removed from the internal Slack directory","All records archived to the ''Offboarded'' HR folder"]'::jsonb, '[{"when":"Employee becomes hostile or uncooperative","action":"Notify the Managing Director immediately. Do not engage further."},{"when":"System access can''t be revoked same-day (IT issue)","action":"IT Head must give a confirmed timeline within 2 hours, or it escalates to the MD."},{"when":"Physical assets not returned (onshore)","action":"The MD handles it directly. Document the outstanding item in the checklist and flag for follow-up."},{"when":"Payroll dispute raised by the departing employee","action":"Direct them to the MD and Bookkeeper. Don''t confirm or deny any figures."},{"when":"Resigning employee, and the MD doesn''t respond within 1 business day","action":"Send one written follow-up. Hold all offboarding steps until confirmed."}]'::jsonb, '["Offboarding Checklist template"]'::jsonb, '["new-hire-onboarding","monthly-payroll-sop"]'::jsonb, '[]'::jsonb, null, '[{"name":"Exec Admin Team","initials":"EXA","date":"27 Aug 2026"}]'::jsonb),
  ('leave-blackout-periods', 'HR-004', 'Leave Blackout Periods & Approval', 'exec', 'current', true, 'Bookkeeper', 'BK', 'Aug 2026', 'Feb 2027', 'v1.0', 'The extra approval layer when a leave request touches a blackout period.', null, '["Confirmed the request touches a blackout date","Requester''s stated reason for leave"]'::jsonb, '[{"name":"Xero","note":"Employees submit leave requests directly here. Accounts Team monitors for new submissions."},{"name":"Private Slack channel","note":"Each contractor''s private channel — used to notify Accounts Team and request the Managing Director''s approval directly."},{"name":"Blackout Period Calendar","note":"Reference list of current-year blackout dates, maintained by Accounts Team and confirmed with the Managing Director annually."},{"name":"Leave Tracker Google Sheet","note":"Logs the outcome of all blackout-period requests. Shared with the standard Leave Request SOP."},{"name":"Slack (Accounts Team ↔ Managing Director)","note":"Used to flag blackout requests and receive the decision."}]'::jsonb, '[{"type":"decision","title":"Which track applies?","body":"The submission channel differs by employment type — everything after this converges into the same review.","options":[{"label":"Track A — Onshore employee (Xero)","detail":"Leave is submitted directly in Xero."},{"label":"Track B — Contractor (private Slack channel)","detail":"Leave is posted in the contractor''s private Slack channel, tagging the Managing Director directly."}]},{"phase":"Submission & check","type":"info","title":"Submit and monitor","body":"Onshore: the employee enters the date range directly in Xero, as normal. Contractor: posts the requested dates and reason for leave in their private channel, tagging the Managing Director for approval. Either way, Accounts Team checks for new submissions at least once per business day."},{"phase":"Submission & check","type":"info","title":"Cross-check against the Blackout Period Calendar","body":"Compare the requested dates against the blackout periods listed above."},{"phase":"Submission & check","type":"decision","title":"Do the dates touch a blackout period?","body":"This is the fork that decides whether this SOP applies at all.","options":[{"label":"No blackout dates involved","detail":"Proceed under the standard process in the Leave Request SOP — stop here."},{"label":"Blackout dates involved (full or partial)","detail":"Mark the request \"Blackout Request\" — in the Xero notes field (onshore) or the Leave Tracker Google Sheet (contractors) — and continue below."}]},{"phase":"Blackout flagging & MD review","type":"info","title":"Flag to the Managing Director via Slack","tags":["approval"],"body":"Send the requester''s name, requested dates, which blackout period applies, and their stated reason for leave."},{"phase":"Blackout flagging & MD review","type":"info","title":"Note the auto-flag status","body":"State clearly in the same message that this request falls in a blackout period and is high-risk / likely to be declined per policy, before it''s reviewed."},{"phase":"Blackout flagging & MD review","type":"info","title":"Await the decision","body":"The Managing Director approves in full, declines, or approves partial dates only."},{"phase":"Blackout flagging & MD review","type":"checklist","title":"Record and notify","items":["Decision recorded — Xero (onshore) or the Leave Tracker Google Sheet (contractors)","Requester notified — Xero notification plus Slack (onshore), or a reply in-thread (contractors)","Team leave calendar updated, only if the request was approved"]}]'::jsonb, '["Requested dates were cross-checked against the Blackout Period Calendar","The request was flagged to the Managing Director with all required details, clearly noted as blackout/high-risk","The decision was received and recorded — Xero (onshore) or the Leave Tracker Google Sheet (contractors)","The requester was notified of the outcome","The team leave calendar was updated, if the request was approved"]'::jsonb, '[{"when":"No reason provided with the request","action":"Accounts Team requests a reason from the requester before flagging anything to the Managing Director."},{"when":"The Managing Director doesn''t respond within 2 business days","action":"Send one follow-up on Slack. If still no response after a further 24 hours, escalate in person."},{"when":"Requester disputes a declined blackout request","action":"Direct them to raise it with the Managing Director directly. Accounts Team does not mediate leave disputes."},{"when":"Blackout date is ambiguous (e.g. Birthday Sale not yet confirmed for the year)","action":"Confirm with the Managing Director before classifying the request as blackout or standard."},{"when":"Late submission (request comes in after the blackout period has already started)","action":"Flag as urgent/late in the message to the Managing Director, in addition to the standard blackout flag."}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["Birthday Sale — dates vary by year; confirmed with the Managing Director at the start of each year.","Australian public holidays — per the official AU public holiday calendar for the applicable state.","All of August — 1–31 August, every year.","November until Christmas — 1 November through 25 December, every year."]'::jsonb, '⚠ Flag for MD review: Birthday Sale dates shift year to year and must be confirmed with the Managing Director before the Blackout Period Calendar is finalized for that year. Until confirmed, treat any late-year request as a possible blackout request and check directly.', '[{"name":"Managing Director","initials":"MD","date":"26 Aug 2026"}]'::jsonb),
  ('monthly-payroll-sop', 'FIN-001', 'Monthly Payroll', 'accounts', 'review-due', true, 'Bookkeeper', 'BK', 'Aug 2026', null, 'v1.0 — pending MD approval', 'Pay run on the last Wednesday of every month — hours, rates, commission, MD sign-off.', null, '["Confirmed pay run date (last Wednesday of the month)","Signed contracts on file for every team member"]'::jsonb, '[{"name":"Xero","note":"Payroll platform for onshore employees — clock-in/out records are pulled from here."},{"name":"Time Doctor","note":"Hours tracking for contractors only."},{"name":"Employee contracts (shared drive)","note":"Source of truth for pay rate, entitlements and commission — never rely on memory."},{"name":"HR-001 Directory Google Form","note":"Bank details and payment info for every team member."},{"name":"Excess Hours Google Sheet","note":"Sent when the last Wednesday falls before month-end, to capture remaining planned hours."}]'::jsonb, '[{"phase":"Pre-payroll preparation","type":"info","title":"Confirm the pay run date","tags":["approval"],"body":"The last Wednesday of the month. If it lands on a public holiday, check with the Managing Director on shifting it a day either way."},{"phase":"Pre-payroll preparation","type":"info","title":"Check for excess days","body":"If days remain in the month after the last Wednesday, the Excess Hours Sheet is needed — otherwise skip straight to gathering pay rates."},{"phase":"Pre-payroll preparation","type":"info","title":"Send the Excess Hours Google Sheet","body":"Share the link via Slack to everyone, with a clear deadline at least 24 hours before the pay run."},{"phase":"Pre-payroll preparation","type":"info","title":"Follow up on missing responses","tags":["approval"],"body":"Chase non-responders directly on Slack. Escalate to the Managing Director rather than estimating or filling in hours on someone''s behalf."},{"phase":"Pre-payroll preparation","type":"checklist","title":"Gather all pay rate references","tags":["confidential"],"body":"Confirm every figure from the signed contract — apply any EA-flagged commission adjustment, not the contract default.","items":["Pay rate confirmed","Onshore vs. offshore/contractor status confirmed","Superannuation applicability confirmed (onshore only)","Commission formula confirmed, if applicable"]},{"phase":"Hours verification","type":"info","title":"Pull onshore employee hours from Xero","body":"Add Excess Hours Sheet entries where applicable. Flag anomalies against the employee''s usual schedule with their manager before proceeding."},{"phase":"Hours verification","type":"info","title":"Tuesday morning: update the Master File with Time Doctor hours","body":"Accounts updates the Master File with the pay period''s accumulated Time Doctor hours, then adds excess hours if applicable and cross-references the total against each contractor''s contract before flagging any discrepancy."},{"phase":"Hours verification","type":"info","title":"Tuesday afternoon: send the Master File out for review","body":"Share the Master File so remaining scheduled hours for the rest of the month can be added, including hours that won''t yet appear in Time Doctor. This is also the checkpoint to review hours, salary and commissions and flag any discrepancies before payroll is submitted."},{"phase":"Hours verification","type":"info","title":"Calculate commission amounts, if applicable","tags":["confidential","approval"],"body":"Confirm the formula from the contract, and apply any adjustment the EA has flagged for this pay period. Escalate unclear or disputed amounts to the Managing Director."},{"phase":"Payroll processing","type":"info","title":"Process onshore employee pay in Xero","tags":["confidential"],"body":"Apply hours, rate, superannuation and commission, then verify the gross pay figure before submitting."},{"phase":"Payroll processing","type":"info","title":"Prepare contractor payment details","tags":["confidential","approval"],"body":"Hours, rate and commission, with bank details from the Directory Form. Never pay a changed account without written confirmation from both the contractor and the MD."},{"phase":"Payroll processing","type":"checklist","title":"Review all figures before processing","tags":["approval"],"body":"One pass across everyone in the pay run before anything is submitted.","items":["Every team member included","Pay rates match contracts","Hours accurate, including excess days","Superannuation applied to all onshore employees","Commission calculated where applicable"]},{"phase":"Payroll processing","type":"info","title":"Wednesday morning: send payroll summary to the MD for approval","tags":["approval","confidential"],"body":"Total headcount, gross payroll, commission amounts and anything unusual — sent via Slack. Payroll is lodged for the Managing Director''s approval — no payment is processed before it''s given in writing."},{"phase":"Payroll processing","type":"info","title":"Wednesday around noon: submit the pay run in Xero","body":"Confirm it''s scheduled for the last Wednesday of the month. Payment processing begins around midday, giving the banks enough time to process the transfers so pay hopefully lands before the end of Wednesday. Save a record to the shared drive."},{"phase":"Payroll processing","type":"info","title":"Process contractor payments","tags":["confidential"],"body":"Same-day as the onshore run, around midday. Confirm each payment initiated and save the records."},{"phase":"Post-payroll wrap-up","type":"info","title":"Notify the Managing Director that payroll is complete","body":"Headcount processed, and anything that needed escalation this cycle."},{"phase":"Post-payroll wrap-up","type":"info","title":"Archive payroll records","tags":["confidential"],"body":"Xero pay run, contractor payments, the Excess Hours Sheet and commission calculations — filed as YYYY-MM_PayrollRecords."},{"phase":"Post-payroll wrap-up","type":"info","title":"Flag any payroll issues for next cycle","body":"Incorrect hours, missing details, bank discrepancies, commission disputes — note them and share with the MD so they''re fixed before the next pay run."}]'::jsonb, '["Pay run processed on the last Wednesday of the month","Excess hours collected where applicable","Onshore hours verified from Xero, contractor hours from Time Doctor","Pay rates confirmed from signed contracts for everyone","Superannuation applied to all onshore employees","Commission calculated and included where applicable","All onshore payments submitted and posted in Xero","All contractor payments initiated to confirmed bank accounts","MD notified that payroll is complete","Payroll records archived under the correct monthly folder"]'::jsonb, '[{"when":"Team member misses the excess-hours deadline","action":"Follow up directly on Slack; escalate to the MD after 2 hours. Never estimate or skip their hours."},{"when":"Pay rate discrepancy vs. contract","action":"Stop payroll for that person, re-check the signed contract, escalate to the MD if still unresolved."},{"when":"Commission amount unclear or disputed","action":"Leave it out of the pay run and escalate to the MD for written confirmation first."},{"when":"Bank details changed since onboarding","action":"Don''t pay the new account until you have written confirmation from both the team member and the MD."},{"when":"Xero error or outage on pay day","action":"Notify the MD immediately. Process contractor payments manually rather than delaying them."}]'::jsonb, '[]'::jsonb, '["new-hire-onboarding","employee-offboarding"]'::jsonb, '[]'::jsonb, null, '[]'::jsonb),
  ('shopify-pos-install-charge', null, 'Charging for a stair install in Shopify POS', 'installations', 'review-due', false, 'Installations Lead', 'IL', 'Aug 2026', 'Jun 2027', 'v1', 'Quick reference: ring up the install-stairs line item and take payment on the floor.', null, '["Shopify POS app open on the terminal"]'::jsonb, '[]'::jsonb, '[{"type":"info","title":"Open the menu","body":"Tap the hamburger menu icon (three lines) at the bottom of the screen."},{"type":"info","title":"Start a Quick Sale","body":"At the bottom of the side menu, tap the blue Quick Sale button."},{"type":"info","title":"Add the product","body":"Tap the Add product button, top left."},{"type":"info","title":"Search for the install line item","body":"Type “Install Stairs” in the search bar, then scroll down to find your location''s install-stairs option and tap it."},{"type":"checklist","title":"Check it before you collect","items":["Correct item selected","Amount matches the job"]},{"type":"info","title":"Collect payment","body":"Tap the black Collect button at the bottom of the screen, then choose the payment method."}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["pre-site-check-install"]'::jsonb, '[]'::jsonb, null, '[]'::jsonb);

